import React, { useState } from 'react';
import './App.css';

function App() {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState('');

  // Your API Gateway Endpoint
  const API_ENDPOINT = "https://6vkpjuest4.execute-api.eu-north-1.amazonaws.com/default/secure-upload-auth";

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleUpload = async (e) => {
    e.preventDefault();
    if (!file) {
      alert("Please select a file first!");
      return;
    }

    setUploading(true);
    setMessage('Getting upload authorization...');

    try {
      // 1. Request the presigned URL from API Gateway
      const response = await fetch(API_ENDPOINT, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          fileName: file.name,
          fileType: file.type,
          fileSize: file.size, // <-- Added file size here
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to get presigned URL from backend.");
      }

      const data = await response.json();

      setMessage('Uploading file directly to S3...');

      // 2. Upload the file directly to S3 using the presigned URL
      const uploadResponse = await fetch(data.uploadUrl, {
        method: "PUT",
        headers: {
          "Content-Type": file.type,
        },
        body: file,
      });

      if (uploadResponse.ok) {
        setMessage('File uploaded successfully! 🎉');
      } else {
        throw new Error("Failed to upload file to S3.");
      }
    } catch (error) {
      console.error("Upload error:", error);
      setMessage('Upload failed: ' + error.message);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div style={{ padding: '40px', fontFamily: 'Arial, sans-serif' }}>
      <h2>Secure File Upload Portal</h2>
      <form onSubmit={handleUpload}>
        <input type="file" onChange={handleFileChange} style={{ marginBottom: '20px', display: 'block' }} />
        <button type="submit" disabled={uploading} style={{ padding: '10px 20px', cursor: 'pointer' }}>
          {uploading ? 'Uploading...' : 'Submit File'}
        </button>
      </form>
      {message && <p style={{ marginTop: '20px', fontWeight: 'bold' }}>{message}</p>}
    </div>
  );
}

export default App;
